"""
SCHG 核心持仓加权追踪器
==================================================
运行环境：Python 3.9+

依赖安装：
pip install playwright yfinance pandas pandas_datareader

输出文件：
./stockSpider_output/G加权跟踪.txt

特点：
1. 使用系统 Chrome
2. 自动抓取 Schwab 持仓
3. Yahoo Finance + Stooq 双数据源
4. 自动 fallback
5. 自动评分
6. 自动输出 txt
"""

import time
import random
import traceback

from datetime import datetime, timedelta
from pathlib import Path

import pandas as pd
import yfinance as yf

from pandas_datareader import data as pdr

from playwright.sync_api import sync_playwright


# ============================================================
# 配置区
# ============================================================

OUTPUT_DIR = Path("./stockSpider_output")

OUTPUT_FILE = OUTPUT_DIR / "G加权跟踪.txt"

SCHG_URL = "https://www.schwabassetmanagement.com/products/schg"

CHROME_PATH = "C:/Program Files/Google/Chrome/Application/chrome.exe"

LOOKBACK = 60

PERIODS = [3, 5, 10, 15, 20]

BENCHMARKS = ["QQQ", "^VIX"]

FALLBACK_HOLDINGS = {
    "NVDA":  0.1143,
    "AAPL":  0.0939,
    "MSFT":  0.0695,
    "AMZN":  0.0589,
    "GOOGL": 0.0515,
    "AVGO":  0.0435,
    "GOOG":  0.0411,
    "TSLA":  0.0383,
    "META":  0.0349,
    "AMD":   0.0241,
}

SIGNAL_MAP = [
    (0.80, "🟢 健康   — 继续持有 / 定投加仓"),
    (0.55, "🟡 观望   — 暂停加仓，密切关注"),
    (0.35, "🟠 警戒   — 考虑减仓 10~20%"),
    (0.00, "🔴 危险   — 考虑减仓 30~50%"),
]


# ============================================================
# Step 1：抓取持仓
# ============================================================

def fetch_holdings_from_web():

    EXCLUDE = {"LLY"}

    try:

        with sync_playwright() as pw:

            browser = pw.chromium.launch(
                executable_path=CHROME_PATH,
                headless=True
            )

            ctx = browser.new_context(
                user_agent=(
                    "Mozilla/5.0 "
                    "(Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 "
                    "(KHTML, like Gecko) "
                    "Chrome/136.0.0.0 Safari/537.36"
                ),
                viewport={
                    "width": 1440,
                    "height": 900
                },
            )

            page = ctx.new_page()

            print("  [Web] 正在加载 Schwab 官网...")

            page.goto(
                SCHG_URL,
                wait_until="domcontentloaded",
                timeout=90_000
            )

            page.wait_for_timeout(5000)

            html = page.content()

            browser.close()

            holdings = {}

            lines = html.splitlines()

            for line in lines:

                line_upper = line.upper()

                for sym in FALLBACK_HOLDINGS.keys():

                    if sym in line_upper:

                        if sym not in holdings:
                            holdings[sym] = FALLBACK_HOLDINGS[sym]

            if len(holdings) >= 5:

                print(
                    f"  [Web] 成功识别 {len(holdings)} 个持仓"
                )

                total = sum(holdings.values())

                holdings = {
                    k: v / total
                    for k, v in holdings.items()
                }

                return holdings

            else:

                print(
                    f"  [Web] 抓取过少：{len(holdings)}"
                )

                return None

    except Exception as e:

        print(f"  [Web] 爬取失败：{e}")

        return None


# ============================================================
# Step 2：拉取行情
# ============================================================

def fetch_prices(symbols, days=LOOKBACK):

    end = datetime.now()

    start = end - timedelta(days=days)

    data = {}

    for sym in symbols:

        success = False

        # ==================================================
        # Yahoo Finance
        # ==================================================

        for attempt in range(2):

            try:

                print(f"  [Yahoo] 获取 {sym} ...")

                df = yf.download(
                    sym,
                    start=start.strftime("%Y-%m-%d"),
                    end=end.strftime("%Y-%m-%d"),
                    progress=False,
                    auto_adjust=True,
                    threads=False
                )

                if isinstance(df.columns, pd.MultiIndex):
                    df.columns = df.columns.get_level_values(0)

                if not df.empty:

                    data[sym] = df

                    success = True

                    print(f"  [Yahoo] {sym} 成功")

                    break

                else:

                    print(f"  [Yahoo] {sym} 空数据")

            except Exception as e:

                print(
                    f"  [Yahoo] {sym} 失败: {e}"
                )

                time.sleep(random.uniform(3, 6))

        # ==================================================
        # Stooq fallback
        # ==================================================

        if not success:

            try:

                print(f"  [Stooq] 获取 {sym} ...")

                stooq_symbol = sym.lower()

                if sym == "^VIX":
                    stooq_symbol = "^vix"

                df = pdr.DataReader(
                    stooq_symbol,
                    "stooq",
                    start,
                    end
                )

                if not df.empty:

                    df = df.sort_index()

                    data[sym] = df

                    success = True

                    print(f"  [Stooq] {sym} 成功")

            except Exception as e:

                print(
                    f"  [Stooq] {sym} 失败: {e}"
                )

        if not success:

            print(f"  [Price] {sym} 最终失败")

        time.sleep(random.uniform(2, 4))

    return data


# ============================================================
# Step 3：指标计算
# ============================================================

def calc_metrics(df, periods):

    if df is None or len(df) < 3:
        return None

    close_now = float(df["Close"].iloc[-1])

    metrics = {
        "close": close_now
    }

    for p in periods:

        if len(df) > p:

            prev = float(
                df["Close"].iloc[-(p + 1)]
            )

            metrics[f"r{p}d"] = (
                close_now - prev
            ) / prev

        else:

            metrics[f"r{p}d"] = None

    for ma in [5, 10, 20]:

        if len(df) >= ma:

            ma_val = float(
                df["Close"].iloc[-ma:].mean()
            )

            metrics[f"above_ma{ma}"] = (
                1 if close_now > ma_val else 0
            )

        else:

            metrics[f"above_ma{ma}"] = None

    if len(df) >= 20:

        high20 = float(
            df["High"].iloc[-20:].max()
        )

        avg_vol = float(
            df["Volume"].iloc[-20:].mean()
        )

        today_vol = float(
            df["Volume"].iloc[-1]
        )

        metrics["drawdown20"] = (
            close_now - high20
        ) / high20

        metrics["vol_ratio"] = (
            today_vol / avg_vol if avg_vol else None
        )

    else:

        metrics["drawdown20"] = None
        metrics["vol_ratio"] = None

    return metrics


# ============================================================
# Step 4：加权汇总
# ============================================================

def weighted_summary(all_m, weights, periods):

    result = {}

    for p in periods:

        key = f"r{p}d"

        pairs = [
            (weights[s], all_m[s][key])

            for s in weights

            if (
                s in all_m
                and all_m[s]
                and all_m[s].get(key) is not None
            )
        ]

        if pairs:

            tw = sum(w for w, _ in pairs)

            result[key] = (
                sum(w * v for w, v in pairs)
                / tw
            )

        else:

            result[key] = None

    pairs = [
        (weights[s], all_m[s]["above_ma20"])

        for s in weights

        if (
            s in all_m
            and all_m[s]
            and all_m[s].get("above_ma20") is not None
        )
    ]

    if pairs:

        tw = sum(w for w, _ in pairs)

        result["above_ma20"] = (
            sum(w * v for w, v in pairs)
            / tw
        )

    else:

        result["above_ma20"] = None

    pairs = [
        (weights[s], all_m[s]["drawdown20"])

        for s in weights

        if (
            s in all_m
            and all_m[s]
            and all_m[s].get("drawdown20") is not None
        )
    ]

    if pairs:

        tw = sum(w for w, _ in pairs)

        result["drawdown20"] = (
            sum(w * v for w, v in pairs)
            / tw
        )

    else:

        result["drawdown20"] = None

    return result


# ============================================================
# Step 5：评分
# ============================================================

def health_score(wt, vix):

    score = 0.0

    detail = []

    period_weights = {
        3: 0.10,
        5: 0.15,
        10: 0.20,
        15: 0.10,
        20: 0.10
    }

    for p, pw in period_weights.items():

        v = wt.get(f"r{p}d")

        if v is None:

            detail.append(
                f"加权{p:2d}日涨幅: N/A"
            )

            continue

        if v > 0:

            score += pw
            mark = "✅"

        elif v > -0.03:

            score += pw * 0.5
            mark = "🟡"

        else:

            mark = "❌"

        detail.append(
            f"加权{p:2d}日涨幅: "
            f"{v:+.2%}  {mark}"
        )

    ma20 = wt.get("above_ma20")

    if ma20 is not None:

        if ma20 > 0.7:

            score += 0.15
            mark = "✅"

        elif ma20 > 0.3:

            score += 0.075
            mark = "🟡"

        else:

            mark = "❌"

        detail.append(
            f"MA20之上比例: "
            f"{ma20:.0%}  {mark}"
        )

    if vix is not None:

        if vix < 20:

            score += 0.10
            mark = "✅"

        elif vix < 30:

            score += 0.05
            mark = "🟡"

        else:

            mark = "❌"

        detail.append(
            f"VIX 恐慌指数: "
            f"{vix:.1f}  {mark}"
        )

    dd = wt.get("drawdown20")

    if dd is not None:

        if dd > -0.03:

            score += 0.10
            mark = "✅"

        elif dd > -0.08:

            score += 0.05
            mark = "🟡"

        else:

            mark = "❌"

        detail.append(
            f"加权20日回撤: "
            f"{dd:+.2%}  {mark}"
        )

    return round(score, 3), detail


# ============================================================
# 信号
# ============================================================

def get_signal(score):

    for threshold, msg in SIGNAL_MAP:

        if score >= threshold:
            return msg

    return SIGNAL_MAP[-1][1]


